CREATE OR REPLACE FUNCTION transfer_admin(p_community_id UUID, p_new_admin_id UUID) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS ' DECLARE current_user_id UUID; BEGIN current_user_id := auth.uid(); IF NOT EXISTS (SELECT 1 FROM communities WHERE id = p_community_id AND creator_id = current_user_id) THEN RAISE EXCEPTION ''Only the community creator can transfer admin controls.''; END IF; UPDATE communities SET creator_id = p_new_admin_id WHERE id = p_community_id; UPDATE community_members SET role = ''member'' WHERE community_id = p_community_id AND user_id = current_user_id; UPDATE community_members SET role = ''admin'' WHERE community_id = p_community_id AND user_id = p_new_admin_id; END; ';
